using System;using System.IO;using System.Linq;using System.Diagnostics;using System.Collections.Generic;using System.Text.Json;using PortCargo.Core;
class Program {static void Main(string[] args){var rows=new List<object>();foreach(var round in new[]{7,20,50}){var hashes=new HashSet<string>();int fallback=0,miss=0;double maxP=0,sumP=0;var times=new List<double>();for(int i=0;i<1000;i++){var watch=Stopwatch.StartNew();var g=EndlessGenerator.Generate(unchecked(902101+i*104729),round);times.Add(watch.Elapsed.TotalMilliseconds);if(g.UsedFallback)fallback++;var a=new EndlessLayoutAnalysis(g.Data);if(a.CanSolve(2)||!a.CanSolve(3))throw new Exception("difficulty/solvability");var p=a.WinProbability();maxP=Math.Max(maxP,p);sumP+=p;if(p>(round<20?.03:round<50?.005:.001))miss++;if(!hashes.Add(EndlessGenerator.LayoutSignature(g.Data)))throw new Exception("structural duplicate");}times.Sort();rows.Add(new{round,samples=1000,uniqueCanonicalLayouts=hashes.Count,randomConstructionFallbacks=fallback,softDifficultyTargetMisses=miss,meanRandomLegalWinProbability=sumP/1000,maxRandomLegalWinProbability=maxP,generationP50Ms=times[499],generationP95Ms=times[949],generationMaxMs=times[999]});Console.WriteLine(JsonSerializer.Serialize(rows.Last()));}File.WriteAllText(args[0],JsonSerializer.Serialize(new{generatorVersion=EndlessGenerator.Version,runtime=System.Runtime.InteropServices.RuntimeInformation.FrameworkDescription,sampleCount=3000,allSolvableWithThree=true,allUnsolvableWithTwo=true,rows},new JsonSerializerOptions{WriteIndented=true})+"\n");}}
